    def dodaj(self):
        wydanie = self.comboBox.currentText()
        kategoria = self.comboBox_2.currentText()
        osoba = self.lineEdit.text()
        miejsce = self.lineEdit_2.text()
        data = self.dateEdit.date().toString("dd.MM.yyyy")
        modeel = self.lineEdit_3.text()
        id = 1
        with open("plik.txt", "w")as plik:
            plik.write("wydanie "+ wydanie  + ",kategoria "+ kategoria + ",osoba " + osoba + ",miejsce " + miejsce + ",data " +str(data))
        row = self.tableWidget.rowCount()
        self.tableWidget.insertRow(row)
        self.tableWidget.setItem(row,1,QTableWidgetItem(wydanie))
        self.tableWidget.setItem(row, 2, QTableWidgetItem(kategoria))
        self.tableWidget.setItem(row, 3, QTableWidgetItem(str(modeel)))
        self.tableWidget.setItem(row, 4, QTableWidgetItem(str(osoba)))
        self.tableWidget.setItem(row, 5, QTableWidgetItem(str(miejsce)))
        self.tableWidget.setItem(row, 6, QTableWidgetItem(str(data)))
        self.tableWidget.setItem(row, 0, QTableWidgetItem(id + 1))
        self.tableWidget.setItem(row, 7, QTableWidgetItem("Otwarty"))

